/// <summary>
/// clean up table for anything older than 14 days
/// </summary>
static void cleanUpPostSalesOrderCreationProcessingQueue()
{
    utcdatetime cutOffDateTime = DateTimeUtil::addDays(DateTimeUtil::utcNow(), -14);

    METPickDirectorQueue postSalesORderCreationProcessingQueue;
    METPickDirectorQueue::skip(postSalesORderCreationProcessingQueue);

    ttsbegin;
    delete_from postSalesORderCreationProcessingQueue
    where postSalesORderCreationProcessingQueue.CreatedDateTime <= cutOffDateTime;
    ttscommit;
}

/// <summary>
/// skip method for performance purpose
/// </summary>
/// <param name = "_pickDirectorQueue"><c>METPickDirectorQueue</c> record</param>
private static void skip(METPickDirectorQueue _pickDirectorQueue)
{
    _pickDirectorQueue.skipDatabaseLog(true);
    _pickDirectorQueue.skipDataMethods(true);
    _pickDirectorQueue.skipDeleteActions(true);
    _pickDirectorQueue.skipEvents(true);
    _pickDirectorQueue.skipBusinessEvents(true);
}
